from sys import stdin, stdout

def main():
    n = int(stdin.readline())
    heights = list(map(int, stdin.readline().split()))

    max_k = (n + 1) // 2
    results = [0] * max_k

    for k in range(1, max_k + 1):
        min_hours = float('inf')

        for start in range(n - 2 * k + 1):
            current_hours = 0
            for i in range(start, start + 2 * k):
                if i % 2 == 0:
                    current_hours += max(0, heights[i] - heights[i + 1])
                else:
                    current_hours += max(0, heights[i + 1] - heights[i])
            min_hours = min(min_hours, current_hours)

        results[k-1] = min_hours

    stdout.write(' '.join(map(str, results)) + '\n')

if __name__ == "__main__":
    main()
